1	"use server";
2	
3	// Server actions for the native Nxeon webmail client (/dashboard/mail).
4	//
5	// Every action authenticates the caller (`requireUser`, via `resolveMailbox`),
6	// resolves ONLY a mailbox the caller owns, decrypts its stored credential, and
7	// talks to the self-hosted mail server over IMAP/SMTP. Mutating actions are
8	// rate-limited. Bodies are sanitised (`safeHtml`) before leaving the server.
9	//
10	// Signatures are fixed by lib/mail/types.ts — the UI builds against the same
11	// contract, so do not change them here.
12	
13	import nodemailer from "nodemailer";
14	import { requireUser } from "@/lib/auth";
15	import { db } from "@/lib/db";
16	import { decryptSecret } from "@/lib/crypto-box";
17	import { checkRateLimit, type RateLimitOptions } from "@/lib/rate-limit";
18	import {
19	  MAIL_SMTP_HOST,
20	  MAIL_SMTP_PORT,
21	  type ListResult,
22	  type MailboxInfo,
23	  type MailFolder,
24	  type MessageFull,
25	  type MessageSummary,
26	  type SendAttachment,
27	  type SendPayload,
28	} from "@/lib/mail/types";
29	import {
30	  MAIL_TLS_SERVERNAME,
31	  findPreviewPart,
32	  folderRole,
33	  isoDate,
34	  parseMessage,
35	  readFlags,
36	  resolveMailbox,
37	  structureHasAttachments,
38	  toMailAddress,
39	  toMailAddresses,
40	  withImap,
41	  withMailbox,
42	} from "@/lib/mail/imap";
43	import { previewText, safeHtml } from "@/lib/mail/render";
44	import type { ImapFlow } from "imapflow";
45	
46	const PAGE_SIZE = 50;
47	
48	/** Reject with a friendly, throttled error when a per-user limit is exceeded. */
49	function enforceRateLimit(key: string, opts: RateLimitOptions) {
50	  const r = checkRateLimit(key, opts);
51	  if (!r.ok) {
52	    throw new Error(`Too many requests — please wait ${r.retryAfterSec}s and try again.`);
53	  }
54	}
