282	// ---------------------------------------------------------------------------
283	// Sending
284	// ---------------------------------------------------------------------------
285	
286	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
287	
288	/** Parse a comma/semicolon-separated recipient string into validated addresses. */
289	function parseRecipients(input: string | undefined): { list: string[]; invalid: string[] } {
290	  const parts = (input || "")
291	    .split(/[,;]+/)
292	    .map((s) => s.trim())
293	    .filter(Boolean);
294	  const list: string[] = [];
295	  const invalid: string[] = [];
296	  for (const p of parts) {
297	    // Tolerate "Name <addr>" form by extracting the address.
298	    const m = p.match(/<([^>]+)>/);
299	    const addr = (m ? m[1] : p).trim();
300	    if (EMAIL_RE.test(addr)) list.push(addr);
301	    else invalid.push(p);
302	  }
303	  return { list, invalid };
304	}
305	
306	/** Resolve the IMAP path of the mailbox's Sent folder (defaults to "Sent"). */
307	async function findSentPath(client: ImapFlow): Promise<string> {
308	  try {
309	    const list = await client.list();
310	    const sent = list.find((f) => folderRole(f.path, f.specialUse) === "sent");
311	    return sent?.path || "Sent";
312	  } catch {
313	    return "Sent";
314	  }
315	}
316	
317	// Attachment limits — enforced server-side; never trust the client's own caps.
318	const MAX_ATTACHMENTS = 10;
319	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB decoded
320	
321	/** Strip path separators, quotes and control chars from an attachment filename. */
322	function sanitizeAttachmentName(name?: string): string {
323	  if (!name) return "";
324	  const cleaned = Array.from(name)
325	    .filter((ch) => {
326	      const c = ch.codePointAt(0) ?? 0;
327	      if (c < 0x20 || c === 0x7f) return false; // control chars
328	      if (ch === '"' || ch === "\\" || ch === "/") return false;
329	      return true;
330	    })
331	    .join("");
332	  return cleaned.trim().slice(0, 200);
333	}
334	
335	type BuiltAttachment = { filename: string; content: Buffer; contentType: string };
336	
337	/**
338	 * Validate + decode client-supplied attachments. Caps count and total decoded
339	 * size, validates base64, sanitises filenames and defaults the content type.
340	 * Returns the decoded buffers or a friendly error string.
341	 */
342	function decodeAttachments(
343	  input: SendAttachment[] | undefined,
344	): { ok: true; attachments: BuiltAttachment[] } | { ok: false; error: string } {
345	  if (!input || input.length === 0) return { ok: true, attachments: [] };
346	  if (!Array.isArray(input)) return { ok: false, error: "Invalid attachments." };
347	  if (input.length > MAX_ATTACHMENTS) {
348	    return { ok: false, error: `Too many attachments — up to ${MAX_ATTACHMENTS} allowed.` };
349	  }
350	
351	  const out: BuiltAttachment[] = [];
352	  let total = 0;
353	  for (let i = 0; i < input.length; i++) {
354	    const a = input[i];
355	    if (!a || typeof a.contentBase64 !== "string") {
356	      return { ok: false, error: "Invalid attachment data." };
357	    }
358	    // Tolerate a stray "data:*;base64," prefix, then validate the base64.
359	    const b64 = a.contentBase64.replace(/^data:[^;]*;base64,/, "").trim();
360	    if (!/^[A-Za-z0-9+/]*={0,2}$/.test(b64) || b64.length % 4 !== 0) {
361	      return { ok: false, error: "Attachment could not be read (invalid encoding)." };
362	    }
363	    const content = Buffer.from(b64, "base64");
364	    total += content.length;
365	    if (total > MAX_ATTACHMENTS_TOTAL_BYTES) {
366	      return { ok: false, error: "Attachments exceed the 20 MB total limit." };
367	    }
368	    const filename = sanitizeAttachmentName(a.filename) || `attachment-${i + 1}`;
369	    const contentType =
370	      typeof a.contentType === "string" && a.contentType.trim()
371	        ? a.contentType.trim().slice(0, 128)
372	        : "application/octet-stream";
373	    out.push({ filename, content, contentType });
374	  }
375	  return { ok: true, attachments: out };
376	}
