470	// ---------------------------------------------------------------------------
471	// Flags / move / delete
472	// ---------------------------------------------------------------------------
473	
474	/** Set or clear the \Seen or \Flagged flag on a message. */
475	export async function setFlag(
476	  folder: string,
477	  uid: number,
478	  flag: "seen" | "flagged",
479	  value: boolean,
480	  mailboxAddress?: string,
481	): Promise<void> {
482	  const { user, cred } = await resolveMailbox(mailboxAddress);
483	  enforceRateLimit(`mail:flag:${user.id}`, { max: 240, windowMs: 60 * 1000 });
484	  const imapFlag = flag === "seen" ? "\\Seen" : "\\Flagged";
485	  await withMailbox(cred, folder, async (client) => {
486	    if (value) await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
487	    else await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
488	  });
489	}
490	
491	/** Move a message from one folder to another. */
492	export async function moveMessage(
493	  folder: string,
494	  uid: number,
495	  toFolder: string,
496	  mailboxAddress?: string,
497	): Promise<void> {
498	  const { user, cred } = await resolveMailbox(mailboxAddress);
499	  enforceRateLimit(`mail:move:${user.id}`, { max: 120, windowMs: 60 * 1000 });
500	  await withMailbox(cred, folder, async (client) => {
501	    await client.messageMove(String(uid), toFolder, { uid: true });
502	  });
503	}
504	
505	/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
506	export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
507	  const { user, cred } = await resolveMailbox(mailboxAddress);
508	  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });
509	
510	  await withImap(cred, async (client) => {
511	    // Determine the Trash folder path.
512	    let trashPath = "Trash";
513	    try {
514	      const list = await client.list();
515	      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
516	      if (trash) trashPath = trash.path;
517	    } catch {
518	      /* fall back to "Trash" */
519	    }
520	
521	    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
522	    const lock = await client.getMailboxLock(folder);
523	    try {
524	      if (inTrash) {
525	        await client.messageDelete(String(uid), { uid: true });
526	      } else {
527	        await client.messageMove(String(uid), trashPath, { uid: true });
528	      }
529	    } finally {
530	      lock.release();
531	    }
532	  });
533	}
