215	/** Convert an array of imapflow envelope addresses to MailAddress[]. */
216	export function toMailAddresses(list: MessageAddressObject[] | undefined): MailAddress[] {
217	  return (list || []).map(toMailAddress).filter((a) => a.address);
218	}
