9	export type ComposeDraft = {
10	  mode: "new" | "reply" | "replyAll" | "forward";
11	  to: string;
12	  cc: string;
13	  subject: string;
14	  body: string; // plaintext the user edits
15	  quotedHtml?: string; // quoted original, appended below the reply
16	  signature?: string; // plain-text signature / fallback for the text part
17	  signatureHtml?: string; // sanitized rich-signature HTML for the HTML part
18	  signaturePlacement?: SignaturePlacement; // where the signature sits relative to quoted text
19	  inReplyToUid?: number;
20	  replyFolder?: string;
21	};
22	
23	// Attachment limits — mirrored server-side (the server re-validates and is the
24	// source of truth). Kept here only for fast, friendly client-side feedback.
25	const MAX_ATTACHMENTS = 10;
26	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB
27	
28	// A file the user has attached, already read into base64 in the browser.
29	type Attachment = {
30	  id: string;
31	  filename: string;
32	  contentType: string;
33	  size: number; // decoded byte size
34	  contentBase64: string;
35	};
36	
37	function formatBytes(bytes: number): string {
38	  if (bytes < 1024) return `${bytes} B`;
39	  const kb = bytes / 1024;
40	  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
41	  const mb = kb / 1024;
42	  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
43	}
44	
45	// Read a File into raw base64 (stripping the "data:*;base64," prefix).
46	function readFileBase64(file: File): Promise<string> {
47	  return new Promise((resolve, reject) => {
48	    const reader = new FileReader();
49	    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
50	    reader.onload = () => {
51	      const result = String(reader.result || "");
52	      const comma = result.indexOf(",");
53	      resolve(comma >= 0 ? result.slice(comma + 1) : result);
54	    };
55	    reader.readAsDataURL(file);
56	  });
57	}
58	
59	export function Composer({
60	  draft,
61	  onClose,
62	  onSend,
63	}: {
64	  draft: ComposeDraft;
65	  onClose: () => void;
66	  onSend: (payload: SendPayload) => Promise<void>;
67	}) {
68	  const [to, setTo] = useState(draft.to);
69	  const [cc, setCc] = useState(draft.cc);
70	  const [showCc, setShowCc] = useState(!!draft.cc);
71	  const [subject, setSubject] = useState(draft.subject);
72	  const [body, setBody] = useState(draft.body);
73	  const [sending, setSending] = useState(false);
74	  const [error, setError] = useState<string | null>(null);
75	  const [attachments, setAttachments] = useState<Attachment[]>([]);
76	  const [reading, setReading] = useState(false);
77	  const [dragging, setDragging] = useState(false);
78	
79	  const fileInputRef = useRef<HTMLInputElement>(null);
80	  const dragDepth = useRef(0); // ignore nested dragenter/dragleave events
81	
82	  useEffect(() => {
83	    const onKey = (e: KeyboardEvent) => {
84	      if (e.key === "Escape" && !sending) onClose();
85	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") void submit();
86	    };
87	    window.addEventListener("keydown", onKey);
88	    return () => window.removeEventListener("keydown", onKey);
89	    // eslint-disable-next-line react-hooks/exhaustive-deps
90	  }, [to, cc, subject, body, sending, attachments]);
91	
92	  const totalBytes = attachments.reduce((n, a) => n + a.size, 0);
93	
94	  // Read a batch of picked/dropped files, enforcing count + total-size caps.
95	  async function addFiles(files: FileList | File[]) {
96	    const list = Array.from(files);
97	    if (list.length === 0) return;
98	    setError(null);
99	
100	    let count = attachments.length;
101	    let running = totalBytes;
102	    const next: Attachment[] = [];
103	    setReading(true);
104	    try {
105	      for (const file of list) {
106	        if (count >= MAX_ATTACHMENTS) {
107	          setError(`You can attach up to ${MAX_ATTACHMENTS} files.`);
108	          break;
109	        }
110	        if (running + file.size > MAX_ATTACHMENTS_TOTAL_BYTES) {
111	          setError(`Attachments can total at most ${formatBytes(MAX_ATTACHMENTS_TOTAL_BYTES)}.`);
112	          break;
113	        }
114	        try {
115	          const contentBase64 = await readFileBase64(file);
116	          next.push({
117	            id: `${Date.now()}-${count}-${Math.random().toString(36).slice(2, 8)}`,
118	            filename: file.name || "attachment",
119	            contentType: file.type || "application/octet-stream",
120	            size: file.size,
121	            contentBase64,
122	          });
123	          count += 1;
124	          running += file.size;
125	        } catch (e) {
126	          setError(e instanceof Error ? e.message : "Could not read a file.");
127	        }
128	      }
129	      if (next.length) setAttachments((prev) => [...prev, ...next]);
130	    } finally {
131	      setReading(false);
132	    }
133	  }
134	
135	  function removeAttachment(id: string) {
