145	  }
146	
147	  const title =
148	    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";
149	
150	  async function submit() {
151	    if (sending || reading) return;
152	    if (!to.trim()) {
153	      setError("Add at least one recipient.");
154	      return;
155	    }
156	    setError(null);
157	    setSending(true);
158	    try {
159	      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
160	      // Compose the outgoing body. User text becomes the text part and, combined
161	      // with any quoted original + signature, the HTML part.
162	      const escaped = esc(body);
163	
164	      // Signature: prefer the sanitized rich-HTML signature; fall back to the
165	      // legacy plain-text one. `signatureHtml` is already sanitized server-side,
166	      // but we re-sanitize here as defence in depth.
167	      const sigPlain = draft.signature?.trim();
168	      const sigRichRaw = draft.signatureHtml?.trim();
169	      const sigRich = sigRichRaw ? safeHtml(sigRichRaw) : "";
170	      const sigText = sigPlain ? `\n\n-- \n${sigPlain}` : "";
171	      const sigHtml = sigRich
172	        ? `<br><br><div class="nx-sig">${sigRich}</div>`
173	        : sigPlain
174	          ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sigPlain)}</div>`
175	          : "";
176	
177	      const userDiv = `<div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${escaped}</div>`;
178	      const quoteHtml = draft.quotedHtml
