231	        {/* Drag-and-drop overlay */}
232	        {dragging && (
233	          <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-navy-950/80 backdrop-blur-sm">
234	            <div className="flex flex-col items-center gap-2 rounded-xl border-2 border-dashed border-brand-400/60 bg-white/[0.04] px-8 py-6 text-brand-200">
235	              <Icon.paperclip size={22} />
236	              <span className="text-sm font-medium">Drop files to attach</span>
237	            </div>
238	          </div>
239	        )}
240	
241	        {/* Header */}
242	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
243	          <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
244	            <span className="text-brand-300"><Icon.compose size={16} /></span>
245	            {title}
246	          </h3>
247	          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
248	            <Icon.close size={16} />
249	          </button>
250	        </div>
251	
252	        {/* Fields */}
253	        <div className="flex-1 overflow-y-auto">
