231	/** Renders the email body. HTML is dropped into a fully sandboxed iframe (no
232	 *  allow-scripts, no allow-same-origin) so hostile markup/scripts cannot run or
233	 *  reach cookies/storage. Plaintext falls back to a pre block. */
234	function MessageBody({ html, text }: { html: string | null; text: string | null }) {
235	  const ref = useRef<HTMLIFrameElement>(null);
236	  const [height, setHeight] = useState(320);
237	
238	  const doc = html
239	    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
240	        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
241	        body{padding:16px;}
242	        img{max-width:100%;height:auto;}
243	        a{color:#5f2ee8;}
244	        table{max-width:100%;}
245	        pre{white-space:pre-wrap;}
246	        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
247	      </style></head><body>${html}</body></html>`
248	    : null;
249	
250	  // Best-effort autosize: with sandbox="" we cannot read the inner document, so
251	  // grow to a comfortable default and let the iframe scroll for very tall mail.
252	  useEffect(() => {
253	    setHeight(html ? 480 : 0);
254	  }, [html]);
255	
256	  if (doc) {
257	    return (
258	      <iframe
259	        ref={ref}
260	        sandbox=""
261	        srcDoc={doc}
262	        title="Message content"
263	        className="w-full rounded-xl border border-white/[0.06] bg-white"
264	        style={{ height }}
265	      />
266	    );
267	  }
268	
269	  if (text && text.trim()) {
270	    return (
271	      <pre className="whitespace-pre-wrap break-words font-sans text-[14px] leading-relaxed text-slate-300">
272	        {text}
273	      </pre>
274	    );
275	  }
276	
277	  return <p className="text-sm italic text-slate-500">This message has no content.</p>;
278	}
