100	/** Load the current settings for a mailbox the caller owns. */
101	export async function getMailboxSettings(mailboxAddress?: string): Promise<MailboxSettings> {
102	  const { mailboxId, address } = await resolveMailbox(mailboxAddress);
103	  const row = await db.mailbox.findUnique({ where: { id: mailboxId } });
104	  const placement = row?.signaturePlacement === "above" ? "above" : "below";
105	  return {
106	    address,
107	    domain: domainOf(address),
108	    displayName: row?.displayName ?? "",
109	    replyTo: row?.replyTo ?? "",
110	    organization: row?.organization ?? "",
111	    signature: row?.signature ?? "",
112	    signatureHtml: row?.signatureHtml ?? "",
113	    signatureEnabled: row?.signatureEnabled ?? true,
114	    signatureOnReply: row?.signatureOnReply ?? true,
115	    signaturePlacement: placement,
116	    autoReplyEnabled: row?.autoReplyEnabled ?? false,
117	    autoReplySubject: row?.autoReplySubject ?? "",
118	    autoReplyBody: row?.autoReplyBody ?? "",
119	    autoReplyStart: toDateInput(row?.autoReplyStart),
120	    autoReplyEnd: toDateInput(row?.autoReplyEnd),
121	    forwardingAddress: row?.forwardingAddress ?? "",
122	    forwardKeepCopy: row?.forwardKeepCopy ?? true,
123	    quotaMB: row?.quotaMB ?? null,
124	  };
125	}
