288	export type AliasRow = { id: number; address: string; goto: string; active: boolean };
289	
290	function toAliasRows(list: MailcowAlias[]): AliasRow[] {
291	  return list.map((a) => ({ id: a.id, address: a.address, goto: a.goto, active: a.active }));
292	}
