294	/** List the aliases on the mailbox's domain. */
295	export async function listAliases(
296	  mailboxAddress?: string,
297	): Promise<{ ok: boolean; error?: string; aliases: AliasRow[] }> {
298	  const { user, address } = await resolveMailbox(mailboxAddress);
299	  const domain = domainOf(address);
300	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet.", aliases: [] };
301	
302	  const owned = await ownedDomains(user.id);
303	  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain.", aliases: [] };
304	
305	  try {
306	    const list = await mcListAliases(domain);
307	    return { ok: true, aliases: toAliasRows(list) };
308	  } catch (e) {
309	    return { ok: false, error: friendly(e), aliases: [] };
310	  }
311	}
312	
313	/**
314	 * Add an alias on a domain the caller owns. `alias` may be a full address or a
315	 * bare local part (the mailbox's own domain is assumed). `goto` defaults to the
316	 * mailbox itself.
317	 */
318	export async function addAlias(alias: string, goto?: string, mailboxAddress?: string): Promise<Result> {
319	  const { user, address } = await resolveMailbox(mailboxAddress);
320	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
321	  if (limited) return limited;
322	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
323	
324	  let aliasAddr = (alias ?? "").trim().toLowerCase();
325	  if (!aliasAddr) return { ok: false, error: "Enter an alias address." };
326	  // Accept a bare local part — assume the mailbox's own domain.
327	  if (!aliasAddr.includes("@")) aliasAddr = `${aliasAddr}@${domainOf(address)}`;
328	  if (!EMAIL_RE.test(aliasAddr)) return { ok: false, error: "That doesn't look like a valid email address." };
329	
330	  const owned = await ownedDomains(user.id);
331	  if (!owned.has(domainOf(aliasAddr))) {
332	    return { ok: false, error: "You can only add aliases on a domain you own." };
333	  }
334	
335	  const dest = (goto ?? "").trim() || address;
336	  if (!EMAIL_RE.test(dest)) return { ok: false, error: "The destination address is not valid." };
337	  if (dest.toLowerCase() === aliasAddr) return { ok: false, error: "An alias can't point to itself." };
338	
339	  try {
340	    await mcAddAlias(aliasAddr, dest);
341	    return { ok: true };
342	  } catch (e) {
343	    return { ok: false, error: friendly(e) };
344	  }
345	}
346	
347	/** Remove an alias by id, after verifying it lives on a domain the caller owns. */
348	export async function removeAlias(id: number, mailboxAddress?: string): Promise<Result> {
349	  const { user, address } = await resolveMailbox(mailboxAddress);
350	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
351	  if (limited) return limited;
352	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
353	  if (!Number.isFinite(id)) return { ok: false, error: "Invalid alias." };
354	
355	  const domain = domainOf(address);
356	  const owned = await ownedDomains(user.id);
357	  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain." };
358	
359	  try {
360	    // Confirm the alias belongs to this owned domain before deleting.
361	    const list = await mcListAliases(domain);
362	    const match = list.find((a) => a.id === id);
363	    if (!match) return { ok: false, error: "That alias no longer exists on your domain." };
364	    await mcDeleteAlias(id);
365	    return { ok: true };
366	  } catch (e) {
367	    return { ok: false, error: friendly(e) };
368	  }
369	}
