374	
375	/** Reset the mailbox password; returns the new password once for the customer. */
376	export async function resetPassword(
377	  mailboxAddress?: string,
378	): Promise<{ error?: string; password?: string }> {
379	  const { mailboxId } = await resolveMailbox(mailboxAddress);
380	  return resetMailboxPassword(mailboxId);
381	}
