383	/** Turn a thrown error into a short, safe message for the UI. */
384	function friendly(e: unknown): string {
385	  const msg = e instanceof Error ? e.message : String(e);
386	  return msg.replace(/\s+/g, " ").slice(0, 200) || "Something went wrong. Please try again.";
387	}
