10	/**
11	 * Image upload for the webmail SIGNATURE editor.
12	 *
13	 * POST /api/mail/signature-image  (multipart/form-data: file) — the signed-in
14	 * mailbox owner picks an image from their computer; we validate its real bytes
15	 * (signature sniff rejects SVG/non-images, cap 5 MB), store the bytes in
16	 * Postgres under the user's id, and return an ABSOLUTE https URL:
17	 *
18	 *   { url: "https://nxeon.cloud/api/mail/signature-image/<cuid>" }
19	 *
20	 * The editor inserts that URL as an <img src>. It is absolute (not a relative
21	 * "/api/…" path) so the image also loads in the RECIPIENT'S external mail
22	 * client, which has no notion of our origin. We host rather than inline because
23	 * `safeHtml` strips `data:` URLs and email clients block inline data images.
24	 *
25	 * Only authenticated owners may upload (requireUser). Per-user + per-IP rate
26	 * limited. To keep storage bounded we cap the number of images per user and
27	 * prune the oldest when over the cap.
28	 */
29	
30	const MAX_IMAGES_PER_USER = 20;
31	
32	function clientIp(req: Request): string {
33	  const xff = req.headers.get("x-forwarded-for") ?? "";
34	  const first = xff.split(",")[0]?.trim();
35	  return first || "unknown";
36	}
37	
38	export async function POST(req: Request) {
39	  let user;
40	  try {
41	    user = await requireUser();
42	  } catch {
43	    return NextResponse.json({ error: "You must be signed in to upload an image." }, { status: 401 });
44	  }
45	
46	  const rl = checkRateLimit(`sig-image:${user.id}:${clientIp(req)}`, { max: 15, windowMs: 60_000 });
47	  if (!rl.ok) {
48	    return NextResponse.json(
49	      { error: "Too many uploads. Please slow down." },
50	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
51	    );
52	  }
53	
54	  let form: FormData;
55	  try {
56	    form = await req.formData();
57	  } catch {
58	    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
59	  }
60	
61	  const file = form.get("file");
62	  if (!(file instanceof File)) {
63	    return NextResponse.json({ error: "No image provided." }, { status: 400 });
64	  }
65	  // Cheap guard before buffering the whole body into memory.
66	  if (file.size > MAX_ATTACHMENT_BYTES) {
67	    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
68	  }
69	
70	  const bytes = Buffer.from(await file.arrayBuffer());
71	  const check = validateImageBytes(bytes, file.type);
72	  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });
73	
74	  const created = await db.signatureImage.create({
75	    data: {
76	      userId: user.id,
77	      mime: check.mime,
78	      sizeBytes: check.bytes.length,
79	      data: new Uint8Array(check.bytes),
80	    },
81	    select: { id: true },
82	  });
83	
84	  // Keep storage bounded: prune the user's oldest images beyond the cap.
85	  try {
86	    const old = await db.signatureImage.findMany({
87	      where: { userId: user.id },
88	      orderBy: { createdAt: "desc" },
89	      skip: MAX_IMAGES_PER_USER,
90	      select: { id: true },
91	    });
92	    if (old.length > 0) {
93	      await db.signatureImage.deleteMany({ where: { id: { in: old.map((r) => r.id) } } });
94	    }
95	  } catch {
96	    /* pruning is best-effort — never fail the upload over it */
97	  }
98	
99	  return NextResponse.json({ url: `${appUrl()}/api/mail/signature-image/${created.id}` });
100	}
