260	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
261	  // strikethrough shown on the pricing page is the real renewal price and this
262	  // discounted value is the real first-term price — displayed === charged.
263	  const promo = currentPromo(new Date());
264	  const chargeCents = promoPriceCents(plan.priceCents, promo);
265	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
266	  if (user.balanceCents < chargeCents) {
267	    return { error: "Insufficient balance. Top up your wallet first." };
268	  }
269	
270	  try {
