272	      await debitWallet(tx, user.id, chargeCents);
273	      await tx.walletTransaction.create({
274	        data: {
275	          userId: user.id,
276	          amountCents: -chargeCents,
277	          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
278	        },
279	      });
280	      await tx.emailSubscription.create({
281	        data: {
282	          userId: user.id,
283	          domainName: name,
284	          emailPlanId: plan.id,
