379	      label: "SPF",
380	      host: domain,
381	      value: SPF_VALUE,
382	      note: "Authorizes the Nxeon mail server to send for your domain.",
383	    },
384	    {
385	      type: "TXT",
386	      label: "DKIM",
387	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
