726	/**
727	 * Store a customer's Cloudflare API token (encrypted) so we can create their
728	 * mail DNS records for them. The token is verified against Cloudflare before it
729	 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
730	 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
731	 */
732	export async function saveCloudflareToken(token: string): Promise<Result> {
733	  const user = await requireUser();
734	
735	  const t = String(token ?? "").trim();
736	  if (!t) return { error: "Paste your Cloudflare API token." };
737	  if (t.length < 20 || t.length > 200) {
738	    return { error: "That doesn't look like a Cloudflare API token." };
739	  }
740	
741	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
742	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
743	
744	  let valid = false;
745	  try {
746	    valid = await cfVerifyToken(t);
747	  } catch (e) {
748	    console.warn("[cloudflare] token verify failed:", e);
749	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
750	  }
751	  if (!valid) {
752	    return {
753	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
754	    };
755	  }
756	
757	  await db.user.update({
758	    where: { id: user.id },
759	    data: { cloudflareTokenEnc: encryptSecret(t) },
760	  });
761	  await db.auditLog.create({
762	    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
763	  });
764	  revalidatePath("/dashboard/email");
765	  return { ok: true };
766	}
