361	const REDIRECT_TYPES = ["redirect301", "redirect302", "masked"] as const;
362	
363	export async function setRedirect(
364	  domainId: string,
365	  hostRaw: string,
366	  forwardsTo: string,
367	  type: string
368	): Promise<RedirectsView> {
369	  let ctx;
370	  try {
371	    ctx = await ownedDomain(domainId);
372	  } catch (e) {
373	    return { forwards: [], live: false, error: errMsg(e) };
374	  }
375	  const host = normHost(hostRaw);
376	  const t = (REDIRECT_TYPES as readonly string[]).includes(type) ? type : "redirect301";
377	  const url = z.string().url().max(2000).safeParse(forwardsTo.trim());
378	  if (!url.success) return { ...(await listRedirects(domainId)), error: "Enter a valid destination URL (including https://)." };
379	
380	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
381	  if (canLive) {
382	    try {
383	      // Upsert: delete any existing forwarding for this host, then create.
384	      try {
385	        await nc("DELETE", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding/${encodeURIComponent(host)}`);
386	      } catch {
387	        /* none existed */
388	      }
389	      await nc("POST", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`, {
390	        host,
391	        forwardsTo: url.data,
392	        type: t,
393	      });
394	    } catch (e) {
395	      return { ...(await listRedirects(domainId)), error: `Registrar rejected the redirect: ${errMsg(e)}` };
396	    }
397	  } else {
