100	export type StoredCloudflare =
101	  | { kind: "oauth"; creds: CfOauthCreds }
102	  | { kind: "token"; token: string }
103	  | null;
104	
105	/** Encrypt OAuth creds for storage in the existing column. */
106	export function packCreds(creds: CfOauthCreds): string {
107	  return encryptSecret(JSON.stringify({ v: 1, ...creds }));
108	}
