110	/**
111	 * Decrypt + classify whatever is in `User.cloudflareTokenEnc`. A value that
112	 * parses as a JSON object with an accessToken is an OAuth connection; anything
113	 * else non-empty is treated as a legacy pasted API token.
114	 */
115	export function readStoredCloudflare(enc: string | null | undefined): StoredCloudflare {
116	  const raw = decryptSecret(enc);
117	  if (!raw) return null;
118	  const trimmed = raw.trim();
119	  if (trimmed.startsWith("{")) {
120	    try {
121	      const parsed = JSON.parse(trimmed) as Partial<CfOauthCreds>;
122	      if (parsed && typeof parsed.accessToken === "string" && parsed.accessToken) {
123	        return {
124	          kind: "oauth",
125	          creds: {
126	            accessToken: parsed.accessToken,
127	            refreshToken: parsed.refreshToken ?? null,
128	            expiresAt: typeof parsed.expiresAt === "number" ? parsed.expiresAt : null,
129	            scope: parsed.scope ?? null,
130	          },
131	        };
132	      }
133	    } catch {
134	      // Not JSON after all — fall through to the legacy-token branch.
135	    }
136	    return null;
137	  }
138	  return { kind: "token", token: trimmed };
139	}
