24	  const name = String(formData.get("name") ?? "").trim();
25	  if (name.length < 1 || name.length > 60) return { error: "Token name: 1–60 characters." };
26	
27	  const scopesRaw = formData.getAll("scopes").map(String);
28	  const scopes = scopesRaw.filter((s): s is (typeof VALID_SCOPES)[number] =>
29	    (VALID_SCOPES as readonly string[]).includes(s),
30	  );
31	  if (scopes.length === 0) scopes.push("read");
