1	import { createHash } from "node:crypto";
2	import { db } from "./db";
3	import type { User } from "@prisma/client";
4	
5	/**
6	 * Bearer-token authentication for the public REST API (`/api/v1/*`).
7	 *
8	 * Tokens are formatted `nxe_<prefix>_<random>` and only their sha256 hash is
9	 * stored (never the plaintext). Given an incoming request, resolve the bearer
10	 * token to its owning user, honouring `revoked` and `expiresAt`, and stamp
11	 * `lastUsedAt`.
12	 */
13	
14	export const TOKEN_PREFIX = "nxe";
15	
16	/** Extract the raw bearer token from an `Authorization: Bearer …` header. */
17	export function extractBearer(req: Request): string | null {
18	  const header = req.headers.get("authorization") ?? req.headers.get("Authorization");
19	  if (!header) return null;
20	  const match = /^Bearer\s+(.+)$/i.exec(header.trim());
21	  return match ? match[1].trim() : null;
22	}
23	
24	/** sha256 hex hash of a token — the value stored in `ApiToken.tokenHash`. */
25	export function hashToken(token: string): string {
26	  return createHash("sha256").update(token).digest("hex");
27	}
28	
29	export type ApiAuthResult =
30	  | { ok: true; user: User; tokenId: string; scopes: string[] }
31	  | { ok: false; status: number; error: string };
32	
33	/**
34	 * Authenticate an API request by its bearer token.
35	 * Returns the resolved user + token scopes, or a structured error with an
36	 * appropriate HTTP status for the route to return.
37	 */
38	export async function authenticateApiToken(req: Request): Promise<ApiAuthResult> {
39	  const raw = extractBearer(req);
40	  if (!raw) return { ok: false, status: 401, error: "Missing bearer token" };
41	  if (!raw.startsWith(`${TOKEN_PREFIX}_`)) {
42	    return { ok: false, status: 401, error: "Invalid token format" };
43	  }
44	
45	  const tokenHash = hashToken(raw);
46	  const token = await db.apiToken.findUnique({
47	    where: { tokenHash },
48	    include: { user: true },
49	  });
50	
51	  if (!token) return { ok: false, status: 401, error: "Invalid token" };
52	  if (token.revoked) return { ok: false, status: 401, error: "Token has been revoked" };
53	  if (token.expiresAt && token.expiresAt < new Date()) {
54	    return { ok: false, status: 401, error: "Token has expired" };
55	  }
56	  if (!token.user || token.user.suspended) {
57	    return { ok: false, status: 403, error: "Account unavailable" };
58	  }
59	
60	  // Best-effort lastUsedAt stamp — never block the request on this write.
61	  db.apiToken
62	    .update({ where: { id: token.id }, data: { lastUsedAt: new Date() } })
63	    .catch(() => {});
64	
65	  return { ok: true, user: token.user, tokenId: token.id, scopes: token.scopes };
66	}
67	
68	/**
69	 * Whether an authenticated token carries a given scope.
70	 *
71	 * Backward-compat policy: a token with NO scopes recorded (empty array) is
72	 * treated as FULL ACCESS — tokens minted before scoping was enforced keep
73	 * working. Otherwise the token must carry:
74	 *   - the exact requested scope (e.g. `servers:read`), or
75	 *   - the global wildcard `*`, or
76	 *   - the resource wildcard `servers:*` (covers `servers:read`), or
77	 *   - the generic `read` scope, which satisfies any `*:read` request.
78	 */
79	export function tokenHasScope(auth: ApiAuthResult, scope: string): boolean {
80	  if (!auth.ok) return false;
81	  const scopes = auth.scopes;
82	  if (!scopes || scopes.length === 0) return true; // legacy full-access token
83	  if (scopes.includes("*") || scopes.includes(scope)) return true;
84	  const [resource, action] = scope.split(":");
85	  if (resource && scopes.includes(`${resource}:*`)) return true;
86	  if (action === "read" && scopes.includes("read")) return true;
87	  return false;
88	}
