37	/** Generate N human-friendly one-time backup codes (plaintext, for display). */
38	function makeBackupCodes(n = 10): string[] {
39	  return Array.from({ length: n }, () => {
40	    const raw = randomBytes(5).toString("hex"); // 10 hex chars
41	    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
42	  });
