50	export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
51	  const user = await db.user.findUnique({ where: { id: userId } });
52	  if (!user || !user.totpEnabled) return false;
53	  const secret = totpSecretOf(user);
54	  if (!secret) return false;
55	
56	  if (verifyTOTP(secret, code)) return true;
57	
58	  // Fall back to consuming a backup code.
59	  const submitted = hashCode(code);
60	  const idx = user.backupCodes.indexOf(submitted);
61	  if (idx === -1) return false;
62	  const remaining = user.backupCodes.filter((_, i) => i !== idx);
63	  await db.user.update({ where: { id: user.id }, data: { backupCodes: remaining } });
