72	 * existing typed caller (`useState<{secret;otpauthUrl}>`) still compiles; an
73	 * optional `error` is populated when enrolment is refused.
74	 */
75	export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string; error?: string }> {
76	  const user = await requireUser();
77	
78	  // Block enrolment while impersonating: the real acting account must be the
79	  // same account being enrolled, so an admin can't seed a customer's 2FA.
80	  const real = await realUser();
81	  if (!real || real.id !== user.id) {
82	    return { secret: "", otpauthUrl: "", error: "You can't set up 2FA while impersonating another account." };
83	  }
84	
85	  // Refuse to overwrite an ALREADY-ACTIVE secret — doing so silently disabled
86	  // the user's working 2FA (totpEnabled=false + fresh secret) with no re-auth.
87	  if (user.totpEnabled === true) {
88	    return { secret: "", otpauthUrl: "", error: "Disable your current 2FA first." };
89	  }
