// ---------- Profile ----------

export async function updateProfile(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  if (name.length < 1 || name.length > 100) return { error: "Enter a valid name." };
  await db.user.update({ where: { id: user.id }, data: { name } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

export async function changePassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const current = String(formData.get("current") ?? "");
  const next = String(formData.get("next") ?? "");
  if (next.length < 8) return { error: "New password must be at least 8 characters." };
  if (!(await bcrypt.compare(current, user.passwordHash))) return { error: "Current password is incorrect." };
  // Bump sessionVersion to evict every other outstanding session, then re-issue a
  // fresh token for THIS session so the user who changed the password stays in.
  await db.user.update({
    where: { id: user.id },
    data: { passwordHash: await bcrypt.hash(next, 12), sessionVersion: { increment: 1 } },
  });
  await createSession(user.id);
  return { ok: true };
}

// ---------- SSH keys ----------

export async function addSshKey(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  const parsed = z
    .object({
      name: z.string().min(1).max(60),
      publicKey: z.string().min(20).max(4000).regex(/^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/, "Not a valid OpenSSH public key"),
    })
    .safeParse({ name: formData.get("name"), publicKey: String(formData.get("publicKey") ?? "").trim() });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid key." };
  await db.sshKey.create({ data: { userId: user.id, ...parsed.data } });
  revalidatePath("/dashboard/settings");
  return {};
}

export async function deleteSshKey(keyId: string) {
  const user = await requireUser();
  await db.sshKey.deleteMany({ where: { id: keyId, userId: user.id } });
  revalidatePath("/dashboard/settings");
}

// ---------- Projects ----------

export async function createProject(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  const color = String(formData.get("color") ?? "#6f47f5");
  if (name.length < 1 || name.length > 50) return { error: "Project name: 1–50 characters." };
  await db.project.create({ data: { userId: user.id, name, color } });
  revalidatePath("/dashboard/projects");
  return {};
}

